import unittest

import mylib as m


class T(unittest.TestCase):
    def test_minimum_hidden(self):
        self.assertEqual(m.minimum([-3, -8]), -8)
        self.assertEqual(m.minimum([2]), 2)

    def test_total_hidden(self):
        self.assertEqual(m.total([]), 0)
        self.assertEqual(m.total([-1, 5]), 4)

    def test_is_palindrome_hidden(self):
        self.assertTrue(m.is_palindrome(''))
        self.assertFalse(m.is_palindrome('ab'))

    def test_first_n_hidden(self):
        self.assertEqual(m.first_n([1, 2], 5), [1, 2])
        self.assertEqual(m.first_n([1, 2, 3], 0), [])


if __name__ == '__main__':
    unittest.main()
